@section('script')
<script>
const announcementStore=@json(route('user.humas.announcements.store',['userId'=>$userId]));
const announcementUpdate=@json(route('user.humas.announcements.update',['userId'=>$userId,'id'=>'__ID__']));
function openAnnouncementCreate(){document.getElementById('announcementTitle').textContent='Buat Pengumuman';document.getElementById('announcementForm').action=announcementStore;document.getElementById('announcementMethod').value='POST';['announcementTitleInput','announcementExcerpt','announcementContent','announcementExpires'].forEach(id=>document.getElementById(id).value='');document.getElementById('announcementCategory').value='umum';document.getElementById('announcementAudience').value='all';document.getElementById('announcementPinned').checked=false;}
function openAnnouncementEdit(btn){const d=JSON.parse(btn.dataset.announcement);document.getElementById('announcementTitle').textContent='Edit Pengumuman';document.getElementById('announcementForm').action=announcementUpdate.replace('__ID__',d.id);document.getElementById('announcementMethod').value='PUT';document.getElementById('announcementTitleInput').value=d.title;document.getElementById('announcementCategory').value=d.category;document.getElementById('announcementAudience').value=d.audience;document.getElementById('announcementExcerpt').value=d.excerpt||'';document.getElementById('announcementContent').value=d.content;document.getElementById('announcementExpires').value=d.expires_at||'';document.getElementById('announcementPinned').checked=!!d.is_pinned;new bootstrap.Modal(document.getElementById('announcementModal')).show();}
</script>
@endsection
